{
  "title": "A slower, different Mexico City day",
  "summary": "We keep the Templo Mayor, then wander to a market, a leafy park, and two easy vegetarian meals in the same part of the city.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The one keeper of the day, and rightly so: old stones with very good stories.",
      "start_by": "15:30"
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "A market swap for the palace, all bustle and local life without the grand staircase.",
      "start_by": "16:00"
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch nearby in the same area, with proper vegetarian plates and no fuss.",
      "start_by": "16:45"
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle Roma Norte wander replaces the castle climb, easy on the legs and lovely on the eyes.",
      "start_by": "open_all_day"
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Lalo!, a bright spot that keeps the vegetarians very happy.",
      "start_by": "16:45"
    }
  ]
}

{
  "title": "A slower, different Mexico City day",
  "summary": "A gentler Thursday that keeps the must-see Templo Mayor, swaps in market life and Chapultepec greenery, and stays in one corner of the city.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The one keeper: Templo Mayor still earns its place, and we start early before the crowds and the heat.",
      "must_do_id": "m2"
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "A swap-in for the palace: Mercado de San Juan gives us street-food energy and local life without the grand staircase."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch stays vegetarian and easy, close to the market so nobody gets hangry on a long ride."
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle Roma Norte wander replaces the castle, with photo spots and coffee-shop pauses built in."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bosque de Chapultepec closes the day with green air and an easy pace, no timed entry to chase."
    }
  ]
}
